or("Supported native cloud scalar required"); if(R.Value<Min || R.Value>Max) throw std::runtime_error("Requested cloud scalar outside field range"); auto* Property=FindFProperty<FFloatProperty>(C->GetClass(),FName(*R.FieldName)); if(!Property) throw std::runtime_error("Native cloud float property unavailable"); const float Before=Property->GetPropertyValue_InContainer(C),Requested=static_cast<float>(R.Value); if(static_cast<double>(Before)!=R.ExpectedValue) throw std::runtime_error("Cloud scalar stale guard failed"); const bool Changed=Before!=Requested;
