FString CloudUtils::Create(const FCloudReq& R)
{
 if(!IsInGameThread() || !GEditor || !GEditor->Trans || GEditor->PlayWorld || !R.bConfirm) throw std::runtime_error("Confirmed stopped editor/transaction system required"); auto* World=GEditor->GetEditorWorldContext().World(); if(!IsValid(World) || World->WorldType!=EWorldType::Editor || World->GetWorldPartition() || !IsValid(World->PersistentLevel)) throw std::runtime_error("Ordinary persistent editor map required"); if(R.Name.IsEmpty() || R.Name.Len()>128 || FName(*R.Name).IsNone() || !FMath::IsFinite(R.Location.X) || !FMath::IsFinite(R.Location.Y) || !FMath::IsFinite(R.Location.Z) || R.Location.GetAbsMax()>1.e9) throw std::runtime_error("Bounded unique name/finite location+/-1e9 required"); for(TCHAR Ch:R.Name) if(!FChar::IsAlnum(Ch) && Ch!=TEXT('_')) throw std::runtime_error("Name requires letters/digits/underscore"); if(FindObject<UObject>(World->PersistentLevel,*R.Name)) throw std::runtime_error("Actor name already exists"); UClass* Class=AVolumetricCloud::StaticClass(); AVolumetricCloud* Actor=nullptr; UVolumetricCloudComponent* Component=nullptr;
 if(!R.bDryRun) { FScopedTransaction Transaction(FText::FromString(TEXT("MCP Create Cloud Actor"))); World->PersistentLevel->Modify(); FActorSpawnParameters Params; Params.Name=FName(*R.Name); Params.OverrideLevel=World->PersistentLevel; Params.ObjectFlags=RF_Transactional; Actor=World->SpawnActor<AVolumetricCloud>(Class,R.Location,FRotator::ZeroRotator,Params); if(!IsValid(Actor)) throw std::runtime_error("Native volumetric-cloud spawn failed; inspect undo transaction"); Component=Actor->FindComponentByClass<UVolumetricCloudComponent>(); if(!IsValid(Component) || !Component->IsRegistered() || Actor->GetWorld()!=World || Actor->GetClass()!=Class) throw std::runtime_error("Native volumetric-cloud registration readback failed; inspect undo transaction"); Actor->Modify(); Actor->MarkPackageDirty(); }
 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("actor_path"),GetPathNameSafe(Actor)); J->WriteValue(TEXT("component_path"),GetPathNameSafe(Component));  J->WriteValue(TEXT("dry_run"),R.bDryRun); J->WriteValue(TEXT("scope"),TEXT("Native volumetric cloud actor spawn in ordinary persistent map, identity rotation/unit scale/native mobility/settings defaults. Native registration may synchronously load default soft material and allocate cloud render resources/PSOs; no build/render sync/save. Native renderer selection/material/scalability settings determine contribution; contribution/undo/persistence unverified.")); J->WriteObjectEnd(); J->Close(); return Result;
}

FString CloudUtils::Delete(const FCloudReq& R)
{
 if(!IsInGameThread() || !GEditor || !GEditor->Trans || GEditor->PlayWorld || !R.bConfirm) throw std::runtime_error("Confirmed stopped editor/transaction system required"); auto* World=GEditor->GetEditorWorldContext().World(); if(!IsValid(World) || World->WorldType!=EWorldType::Editor || World->GetWorldPartition() || R.ActorPath.IsEmpty() || R.ActorPath.Len()>2048 || R.ComponentPath.IsEmpty() || R.ComponentPath.Len()>2048) throw std::runtime_error("Ordinary editor map/bounded cloud identities required"); auto* Actor=FindObject<AVolumetricCloud>(nullptr,*R.ActorPath); if(!IsValid(Actor) || Actor->IsTemplate() || Actor->HasAnyFlags(RF_Transient) || Actor->GetWorld()!=World || Actor->GetLevel()!=World->PersistentLevel || !IsValid(Actor->FindComponentByClass<UVolumetricCloudComponent>()) || Actor->FindComponentByClass<UVolumetricCloudComponent>()->GetPathName()!=R.ComponentPath) throw std::runtime_error("Persistent-level cloud actor and inspected component required"); auto* C=Actor->FindComponentByClass<UVolumetricCloudComponent>(); TArray<AActor*> Attached; Actor->GetAttachedActors(Attached); if(Attached.Num()) throw std::runtime_error("Detach attached actors before cloud deletion");
 if(!R.bDryRun) { FScopedTransaction Transaction(FText::FromString(TEXT("MCP Delete Cloud"))); World->PersistentLevel->Modify(); Actor->Modify(); C->Modify(); if(!World->EditorDestroyActor(Actor,true)) throw std::runtime_error("Native cloud destruction failed; inspect undo transaction"); World->PersistentLevel->MarkPackageDirty(); }
 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("actor_path"),R.ActorPath); J->WriteValue(TEXT("component_path"),R.ComponentPath); J->WriteValue(TEXT("deleted"),!R.bDryRun); J->WriteValue(TEXT("dry_run"),R.bDryRun); J->WriteValue(TEXT("scope"),TEXT("Native volumetric cloud actor deletion in ordinary persistent map, component identity guards and no attached actors. Level/actor/component transaction; teardown can affect cloud render resources/external references. No explicit render synchronization/save, undo/resource lifecycle/persistence unverified.")); J->WriteObjectEnd(); J->Close(); return Result;
}



FString CloudUtils::SetTransform(const FCloudReq& R)
{
 if(!IsInGameThread() || !GEditor || !GEditor->Trans || GEditor->PlayWorld || !R.bConfirm) throw std::runtime_error("Confirmed stopped editor/transaction system required"); auto* World=GEditor->GetEditorWorldContext().World(); if(!IsValid(World) || World->WorldType!=EWorldType::Editor || R.ActorPath.IsEmpty() || R.ActorPath.Len()>2048 || R.ComponentPath.IsEmpty() || R.ComponentPath.Len()>2048 || !FMath::IsFinite(R.Value) || !FMath::IsFinite(R.ExpectedValue)) throw std::runtime_error("Current world/bounded identities/finite values required"); auto* C=FindObject<UVolumetricCloudComponent>(nullptr,*R.ComponentPath); if(!IsValid(C) || C->IsTemplate() || C->GetWorld()!=World || !IsValid(C->GetOwner()) || C->GetOwner()->GetPathName()!=R.ActorPath || C->GetOwner()->HasAnyFlags(RF_Transient)) throw std::runtime_error("Persistent current cloud actor/component required");
 auto Valid=[](const FTransform& T) { const FVector P=T.GetTranslation(),S=T.GetScale3D(); return !T.ContainsNaN() && T.GetRotation().IsNormalized() && P.GetAbsMax()<=1.e9 && S.GetAbsMax()<=1000 && FMath::Abs(S.X)>=1.e-6 && FMath::Abs(S.Y)>=1.e-6 && FMath::Abs(S.Z)>=1.e-6; }; if(!Valid(R.Transform) || !Valid(R.ExpectedTransform)) throw std::runtime_error("Finite normalized transforms, location+/-1e9 and nonzero scale<=1000 required"); if(C->GetAttachParent()) throw std::runtime_error("Detach cloud component before world-transform editing to avoid parent decomposition ambiguity"); const FTransform Before=C->GetComponentTransform(); if(!Before.Equals(R.ExpectedTransform,1.e-6)) throw std::runtime_error("Cloud world transform stale guard failed"); const bool Changed=!Before.Equals(R.Transform,1.e-6);
 if(!R.bDryRun && Changed) { FScopedTransaction Transaction(FText::FromString(TEXT("MCP Set Cloud Transform"))); C->GetOwner()->Modify(); C->SetFlags(RF_Transactional); C->Modify(); C->SetWorldTransform(R.Transform,false,nullptr,ETeleportType::TeleportPhysics); if(!IsValid(C) || !C->GetComponentTransform().Equals(R.Transform,1.e-4)) throw std::runtime_error("Native cloud transform readback mismatch; inspect undo transaction"); C->MarkPackageDirty(); }
 FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("component_path"),R.ComponentPath); J->WriteValue(TEXT("would_change"),Changed); J->WriteValue(TEXT("dry_run"),R.bDryRun); J->WriteValue(TEXT("scope"),TEXT("Native unattached cloud component authored world transform with inspected full transform guard. Native SetWorldTransform(no sweep/teleport), actor/component transaction, children follow. Cloud layer geometry is driven by altitude/height/planet controls and material; authored transform does not prove cloud-layer translation/rotation/scale or rendered change. No actor construction rerun/lighting build/render sync/save; native callbacks/render/undo/persistence unverified.")); J->WriteObjectEnd(); J->Close(); return Result;
}



FString CloudUtils::InspectWorldPage(const FCloudReq& R)
{
 if(!IsInGameThread() || !GEditor || GEditor->PlayWorld) throw std::runtime_error("Stopped editor world required"); const auto* World=GEditor->GetEditorWorldContext().World(); if(!IsValid(World) || World->WorldType!=EWorldType::Editor) throw std::runtime_error("Current editor world required"); if(R.Start<0 || R.Count<1 || R.Count>128 || R.ActorPath.Len()>2048) throw std::runtime_error("Offset/page1..128/optional bounded owner path required"); TArray<UVolumetricCloudComponent*> Entries; for(TObjectIterator<UVolumetricCloudComponent> It;It;++It) { auto* C=*It; if(!IsValid(C) || C->IsTemplate() || C->HasAnyFlags(RF_Transient|RF_NeedLoad|RF_NeedPostLoad) || C->GetWorld()!=World || !IsValid(C->GetOwner()) || C->GetOwner()->IsTemplate() || C->GetOwner()->HasAnyFlags(RF_Transient|RF_NeedLoad|RF_NeedPostLoad) || (!R.ActorPath.IsEmpty() && C->GetOwner()->GetPathName()!=R.ActorPath)) continue; Entries.Add(C); } Entries.Sort([](const UVolumetricCloudComponent& A,const UVolumetricCloudComponent& B) { return A.GetPathName()<B.GetPathName(); }); const int32 Start=FMath::Min(R.Start,Entries.Num()),End=Start+FMath::Min(R.Count,Entries.Num()-Start); FString Result; auto J=TJsonWriterFactory<>::Create(&Result); J->WriteObjectStart(); J->WriteValue(TEXT("world_path"),World->GetPathName()); const int32 Count=Entries.Num(); J->WriteArrayStart(TEXT("cloud_components")); for(int32 I=Start;I<End;++I) { const auto* C=Entries[I]; J->WriteObjectStart(); J->WriteValue(TEXT("actor_path"),GetPathNameSafe(C->GetOwner())); J->WriteValue(TEXT("actor_class_path"),IsValid(C->GetOwner())?C->GetOwner()->GetClass()->GetPathName():FString()); J->WriteValue(TEXT("index"),I); J->WriteValue(TEXT("actor_guid"),C->GetOwner()->GetActorGuid().ToString()); J->WriteValue(TEXT("label"),C->GetOwner()->GetActorLabel()); J->WriteValue(TEXT("level_path"),GetPathNameSafe(C->GetOwner()->GetLevel())); J->WriteValue(TEXT("package_dirty"),C->GetPackage()->IsDirty()); J->WriteValue(TEXT("component_path"),C->GetPathName()); J->WriteValue(TEXT("class_path"),C->GetClass()->GetPathName()); J->WriteValue(TEXT("registered"),C->IsRegistered()); auto Vector=[&](const TCHAR* Name,const FVector& V) { J->WriteArrayStart(Name); for(double N:{V.X,V.Y,V.Z}) { if(FMath::IsFinite(N)) J->WriteValue(N); else J->WriteNull(); } J->WriteArrayEnd(); }; Vector(TEXT("world_location"),C->GetComponentLocation()); Vector(TEXT("component_scale"),C->GetComponentScale()); const auto Q=C->GetComponentQuat(); J->WriteArrayStart(TEXT("world_rotation_quaternion")); for(double N:{Q.X,Q.Y,Q.Z,Q.W}) { if(FMath::IsFinite(N)) J->WriteValue(N); else J->WriteNull(); } J->WriteArrayEnd(); J->WriteValue(TEXT("attachment_parent_path"),GetPathNameSafe(C->GetAttachParent()));   J->WriteValue(TEXT("visible"),C->GetVisibleFlag()); J->WriteValue(TEXT("material_soft_path"),C->Material.ToSoftObjectPath().ToString()); J->WriteValue(TEXT("resolved_material_path"),C->GetMaterial()?C->GetMaterial()->GetPathName():FString()); J->WriteValue(TEXT("tracing_max_distance_mode"),static_cast<int32>(C->TracingMaxDistanceMode)); auto Number=[&](const TCHAR* Name,double N) { if(FMath::IsFinite(N)) J->WriteValue(Name,N); else J->WriteNull(Name); }; J->WriteObjectStart(TEXT("scalars"));
 Number(TEXT("LayerBottomAltitude"),C->LayerBottomAltitude);
 Number(TEXT("LayerHeight"),C->LayerHeight);
 Number(TEXT("TracingStartMaxDistance"),C->TracingStartMaxDistance);
 Number(TEXT("TracingStartDistanceFromCamera"),C->TracingStartDistanceFromCamera);
 Number(TEXT("TracingMaxDistance"),C->TracingMaxDistance);
 Number(TEXT("PlanetRadius"),C->PlanetRadius);
 Number(TEXT("SkyLightCloudBottomOcclusion"),C->SkyLightCloudBottomOcclusion);
 Number(TEXT("ViewSampleCountScale"),C->ViewSampleCountScale);
 Number(TEXT("ReflectionViewSampleCountScaleValue"),C->ReflectionViewSampleCountScaleValue);
 Number(TEXT("ShadowViewSampleCountScale"),C->ShadowViewSampleCountScale);
 Number(TEXT("ShadowReflectionViewSampleCountScaleValue"),C->ShadowReflectionViewSampleCountScaleValue);
 Number(TEXT("ShadowTracingDistance"),C->ShadowTracingDistance);
 Number(TEXT("StopTracingTransmittanceThreshold"),C->StopTracingTransmittanceThreshold);
 Number(TEXT("AerialPespectiveRayleighScatteringStartDistance"),C->AerialPespectiveRayleighScatteringStartDistance);
 Number(TEXT("AerialPespectiveRayleighScatteringFadeDistance"),C->AerialPespectiveRayleighScatteringFadeDistance);
 Number(TEXT("AerialPespectiveMieScatteringStartDistance"),C->AerialPespectiveMieScatteringStartDistance);
 Number(TEXT("AerialPespectiveMieScatteringFadeDistance"),C->AerialPespectiveMieScatteringFadeDistance);
 J->WriteObjectEnd(); J->WriteObjectStart(TEXT("flags"));
 J->WriteValue(TEXT("bUsePerSampleAtmosphericLightTransmittance"),static_cast<bool>(C->bUsePerSampleAtmosphericLightTransmittance));
 J->WriteValue(TEXT("bHoldout"),static_cast<bool>(C->bHoldout));
 J->WriteValue(TEXT("bRenderInMainPass"),static_cast<bool>(C->bRenderInMainPass));
 J->WriteValue(TEXT("bVisibleInRealTimeSkyCaptures"),static_cast<bool>(C->bVisibleInRealTimeSkyCaptures));
 J->WriteObjectEnd(); J->WriteArrayStart(TEXT("ground_albedo_rgba")); for(int32 N:{static_cast<int32>(C->GroundAlbedo.R),static_cast<int32>(C->GroundAlbedo.G),static_cast<int32>(C->GroundAlbedo.B),static_cast<int32>(C->GroundAlbedo.A)}) J->WriteValue(N); J->WriteArrayEnd(); J->WriteObjectEnd(); } J->WriteArrayEnd(); J->WriteValue(TEXT("component_count"),Count); J->WriteValue(TEXT("next_start"),End); J->WriteValue(TEXT("has_more"),End<Count); J->WriteValue(TEXT("start"),Start); J->WriteValue(TEXT("owner_filter"),R.ActorPath); J->WriteValue(TEXT("scope"),TEXT("Component-path sorted loaded persistent current-world UVolumetricCloudComponent inventory pages1..128, optional exact owner filter. Native authored settings/registration/visibility plus actor GUID/label/level/dirty and safe pagination, no stable revision across calls. Global scans/sorts/custom getters unbounded. No renderer eligibility/output evaluation/capture/build/render synchronization/load/save/mutation; compilation/native paging/serialization unverified.")); J->WriteObjectEnd(); J->Close(); return Result;
}
